routing_rules:
[
  {
    "priority": 1,
    "condition": {
      "field": "tipo_experiencia_implantacao",
      "operator": "eq",
      "value": "premium_personalizado"
    },
    "workflow_id": "wf_triagem_senior_e_pricing_premium",
    "description": "Segmentos complexos exigem validação técnica e pricing dedicado"
  },
  {
    "priority": 2,
    "condition": {
      "field": "tipo_experiencia_implantacao",
      "operator": "eq",
      "value": "implementacao_assistida"
    },
    "workflow_id": "wf_onboarding_assistido_com_hardware",
    "description": "Setup com inventário, POS e formação de equipa"
  },
  {
    "priority": 3,
    "condition": {
      "field": "tipo_experiencia_implantacao",
      "operator": "eq",
      "value": "rapido_padrao"
    },
    "workflow_id": "wf_onboarding_rapido_padrao",
    "description": "Ativação automática, templates pré-configurados"
  },
  {
    "priority": 4,
    "condition": {
      "field": "risco_fiscal_mz",
      "operator": "eq",
      "value": "Critico"
    },
    "workflow_id": "wf_alerta_compliance_urgente",
    "description": "Escalada imediata para equipa de Contabilidade"
  },
  {
    "priority": 5,
    "condition": {
      "field": "score_upsell",
      "operator": "gte",
      "value": 8.0
    },
    "workflow_id": "wf_upsell_premium",
    "description": "Oportunidade de upsell de alta prioridade"
  },
  {
    "priority": 6,
    "condition": {
      "field": "score_upsell",
      "operator": "gte",
      "value": 6.0
    },
    "workflow_id": "wf_upsell_standard",
    "description": "Oportunidade de upsell padrão"
  },
  {
    "priority": 7,
    "condition": {
      "field": "score_upsell",
      "operator": "lt",
      "value": 4.0
    },
    "workflow_id": "wf_triagem_manual_v1",
    "description": "Score baixo ou dados insuficientes → intervenção humana"
  }
